WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS prev_txn_time FROM transactions), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_session FROM with_prev), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT session_id, COUNT(*) AS cnt, ROUND(SUM(session_id) / NULLIF(COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END), 0), 2) AS session_id_per_refund FROM sessionized GROUP BY session_id
